    long testX = x;
    long testY = y;
    if (side == EDGE_SIDE_1)
        --testX;
    else if (side == EDGE_SIDE_3)
        --testY;
    if (testX >= Map->WorldPosX && testX < Map->WorldPosX + Map->MapWidth
        && testY >= Map->WorldPosY && testY < Map->WorldPosY + Map->MapHeight) {
